INSERT INTO noticia (categoria, titulo, fecha, resumen, contenido, imagen) VALUES
(
    'Guías',
    'Arma tu primer Home Studio: Lo esencial para empezar a grabar',
    '2026-09-01',
    'Descubre qué interfaz, micrófono y monitores necesitas para obtener calidad profesional desde tu habitación sin salirte del presupuesto.',
    '<p>Empezar en el mundo de la producción musical puede ser abrumador por la cantidad de opciones disponibles. Sin embargo, no necesitas gastar una fortuna para obtener resultados profesionales.</p><h3 class="fw-bold mt-4 mb-3 text-light">La Interfaz de Audio</h3><p>Es el corazón de tu estudio. Recomendamos interfaces de 2 entradas y 2 salidas para empezar. Esto te permitirá grabar una voz y una guitarra simultáneamente.</p><h3 class="fw-bold mt-4 mb-3 text-light">Monitores vs Audífonos</h3><p>Aunque los audífonos son excelentes para grabar sin retroalimentación, unos buenos monitores de estudio te darán una respuesta "plana", crucial para que tu mezcla suene bien en cualquier sistema de sonido.</p>',
    '../img/monitores-de-estudio-en-home-studio.jpg'
),
(
    'Análisis Musical',
    'Construyendo la atmósfera: El sonido detrás de Alkaline (Sleep Token)',
    '2026-09-05',
    'Un desglose técnico de cómo la mezcla de ecualización precisa y distorsión controlada genera las atmósferas envolventes de esta pista.',
    '<p>Cuando analizamos la producción moderna, pocas bandas logran fusionar géneros con tanta precisión como Sleep Token. En esta publicación, desglosaremos los elementos técnicos que hacen de la pista una experiencia envolvente, ideal para probar la respuesta de frecuencias de tus nuevos monitores de estudio.</p><h3 class="fw-bold mt-4 mb-3 text-light">La química del sonido: Temáticas de pH y estructura</h3><p>Desde la perspectiva de la mezcla, la canción hace honor a su temática química. Las transiciones entre los versos limpios y los estribillos pesados están tratadas con una ecualización muy meticulosa. Es fascinante cómo la estructura simbólica de la letra —con un conteo de sílabas muy particular y metáforas sobre elementos ácidos y alcalinos— se refleja en el diseño sonoro: guitarras afinadas muy graves que actúan como la "acidez" abrasiva, contrastadas por sintetizadores cristalinos y reverberaciones largas que aportan el equilibrio "alcalino".</p><h3 class="fw-bold mt-4 mb-3 text-light">Equipamiento recomendado para recrear el tono</h3><p>Si buscas experimentar con estos contrastes en tu propia música, la clave está en el control de la distorsión. Recomendamos el uso de guitarras de rango extendido, pasadas por pedales de overdrive que ajusten los medios antes de golpear un amplificador de alta ganancia.</p>',
    '../img/donkey-sound-effects-5.avif'
);
